# Tool to test grott data processing.
# Updated: 2026-07-14

from grottconf import Conf
from grottdata import procdata


verrel = "2.8.3"

# Process config file.
conf = Conf(verrel)

# Print configuration.
if conf.verbose:
    conf.print()

# Specify overwrite .ini data.
conf.nomqtt = True

# Candidate-tree protocol-06 record: the two serial fields are pseudonymized
# and the CRC regenerated. Existing Git ancestry was not remediated.
xdata = ""

data = bytes.fromhex(xdata)
procdata(conf, data)
